const items = $input.all();
const now = new Date();
const breaches = [];

for (const item of items) {
  const createdAt = new Date(item.json.created_at);
  const ageMinutes = (now - createdAt) / 1000 / 60;

  let breached = false;
  let breachType = "";

  if (item.json.priority === "Emergency" && ageMinutes > 15) {
    breached = true;
    breachType = "Emergency not handled in 15 minutes";
  } else if (item.json.category === "Standard Maintenance" && ageMinutes > 1440) {
    breached = true;
    breachType = "Standard maintenance untouched after 24 hours";
  } else if (item.json.status === "Assigned" && ageMinutes > 120) {
    breached = true;
    breachType = "Vendor no response after 2 hours";
  }

  if (breached) {
    breaches.push({
      ...item.json,
      breach_type: breachType,
      age_minutes: Math.round(ageMinutes),
      breach_detected_at: now.toISOString()
    });
  }
}

return breaches;

